import {citizenModel,chapterTwoMaterials} from './chapter-two-models.js';
import {roundedBox} from './rounded-geometry.js';
import * as T from './vendor/three.module.js';
const loader=new T.TextureLoader();T.DefaultLoadingManager.onProgress=(_url,loaded,total)=>{const label=document.querySelector('#save-status');if(label&&document.querySelector('#start')?.disabled)label.textContent='Загрузка текстур: '+loaded+' / '+total};T.DefaultLoadingManager.onError=()=>{const label=document.querySelector('#save-status');if(label)label.textContent='Не удалось загрузить текстуру. Проверьте соединение и обновите страницу.'};
const names=['волк_шерсть','волк_морда','волк_лапы','заяц_шерсть','заяц_морда','заяц_уши','ворон_перья','ворон_крыло','ворон_голова'];
const textures=Object.fromEntries(await Promise.all(names.map(async n=>{const t=await loader.loadAsync('./assets/'+n+'.webp');t.colorSpace=T.SRGBColorSpace;return [n,t]})));
const witchAtlas=await loader.loadAsync('./assets/ведьма_атлас.webp');witchAtlas.colorSpace=T.SRGBColorSpace;
for(const [name,x,y] of [['ведьма_лицо',0,.5],['ведьма_роба',.5,.5],['ведьма_кожа',0,0],['ведьма_шляпа',.5,0]]){const t=witchAtlas.clone();t.repeat.set(.5,.5);t.offset.set(x,y);textures[name]=t}
export function witchMaterial(name){return material('ведьма_'+name)}
const sets={wolf:['волк_шерсть','волк_морда','волк_лапы','волк_шерсть'],hare:['заяц_шерсть','заяц_морда','заяц_шерсть','заяц_шерсть'],raven:['ворон_перья','ворон_голова','ворон_перья','ворон_крыло']};
function material(name){return new T.MeshStandardMaterial({...textures[name]?{map:textures[name]}:{},roughness:.9,flatShading:false})}

let peoplePalette;
function villagePerson(scene,x,z,height,role){peoplePalette??=chapterTwoMaterials();peoplePalette.load();const woman=role==='woman',n=citizenModel(scene,x,z,{id:'local-'+role,name:role,role:role==='hunter'?'citizen':role==='witch'?'mage':role==='digger'?'elder':role,woman,scale:height/1.95,cloth:woman?6:role==='smith'?5:role==='witch'?10:3},peoplePalette);const cue=n.cueAttack;n.cueAttack=(kind,duration)=>cue(kind==='bow'?'crossbow':kind==='magic'?'mage':kind,duration);n.height=height;n.x=x;n.z=z;const animate=n.update;n.update=()=>{};n.animate=dt=>animate(dt);n.g.userData.hitRig=n.g;
 if(role==='digger'){const shovel=new T.Group();n.g.userData.arms[1].add(shovel);n.g.userData.shovel=shovel;shovel.position.set(0,-.5,0);const shaft=new T.Mesh(new T.CylinderGeometry(.025,.025,1.4,7),new T.MeshStandardMaterial({color:0x765439}));shaft.position.y=.3;shovel.add(shaft);const blade=new T.Mesh(new T.BoxGeometry(.24,.32,.06),new T.MeshStandardMaterial({color:0x839397,metalness:.5}));blade.position.y=-.48;shovel.add(blade)}
 if(role==='hunter'){const bow=new T.Group();n.g.userData.arms[0].add(bow);bow.position.set(0,-.5,.1);const curve=new T.QuadraticBezierCurve3(new T.Vector3(0,-.45,0),new T.Vector3(0,0,.3),new T.Vector3(0,.45,0));bow.add(new T.Mesh(new T.TubeGeometry(curve,16,.025,6,false),new T.MeshStandardMaterial({color:0x8b643b})));const string=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(0,-.45,0),new T.Vector3(0,0,0),new T.Vector3(0,.45,0)]),new T.LineBasicMaterial({color:0xd1c7aa}));bow.add(string);n.g.userData.bow=bow;n.g.userData.string=string}
 return n;
}
export function modelActor(scene,maps,x,z,height,animal=false,role="guard"){
if(!animal)return villagePerson(scene,x,z,height,role);
const g=new T.Group();g.position.set(x,0,z);scene.add(g);const limbs=[];
const selected=sets[animal===true?'wolf':animal||role];const body=material(selected[0]),face=material(selected[1]),legs=material(selected[2]),sleeves=material(selected[3]),skin=material(animal?selected[0]:'человек_кожа'),hair=material('волосы');
const headMaterials=[skin,skin,animal?skin:hair,skin,face,animal?skin:hair];
function part(parent,w,h,d,px,py,pz,material){const m=new T.Mesh(roundedBox(w,h,d),material);m.position.set(px,py,pz);parent.add(m);return m}
function limb(px,py,pz,w,h,d,cover=legs){const joint=new T.Group();joint.position.set(px,py,pz);g.add(joint);part(joint,w,h,d,0,-h/2,0,cover);limbs.push(joint)}
if(animal==='hare'){
const oval=(w,h,d,x,y,z,mat)=>{const m=new T.Mesh(new T.SphereGeometry(1,12,10),mat);m.scale.set(w/2,h/2,d/2);m.position.set(x,y,z);g.add(m);return m};
oval(.62,.65,.69,0,.49,-.12,body);oval(.37,.36,.36,0,.72,.27,face);oval(.23,.20,.16,0,.64,.45,skin);oval(.22,.22,.22,0,.47,-.51,skin);
for(const side of [-1,1]){const ear=oval(.12,.67,.075,side*.10,1.13,.23,material('заяц_уши'));ear.rotation.z=side*.14;oval(.27,.38,.34,side*.22,.30,-.20,body);limb(side*.14,.35,.25,.09,.24,.12);oval(.18,.10,.28,side*.23,.10,-.08,legs);const eye=oval(.045,.065,.045,side*.145,.77,.385,new T.MeshStandardMaterial({color:0x171215,roughness:.2}));}oval(.07,.055,.04,0,.68,.535,new T.MeshStandardMaterial({color:0xbe8c8c}));
}else if(animal==='raven'){part(g,.34,.48,.48,0,.52,0,body);part(g,.24,.25,.28,0,.88,.16,[face,face,body,body,body,body]);const beak=new T.Mesh(new T.ConeGeometry(.10,.30,4),new T.MeshStandardMaterial({color:0x252a30}));beak.rotation.x=Math.PI/2;beak.position.set(0,.88,.42);g.add(beak);for(const side of [-1,1]){limb(side*.10,.33,0,.05,.30,.06);part(g,.08,.35,.45,side*.20,.56,0,sleeves);}}else{part(g,.42,.43,.94,0,.67,0,body);part(g,.32,.35,.38,0,.88,.52,headMaterials);part(g,.22,.17,.29,0,.81,.79,body);for(const side of [-1,1]){const ear=new T.Mesh(new T.ConeGeometry(.10,animal==="hare"?.65:.24,4),animal==="hare"?material("заяц_уши"):skin);ear.position.set(side*.12,1.15,.53);g.add(ear);for(const z of [-.32,.32])limb(side*.18,.58,z,.12,.53,.14)}const tail=part(g,.12,.12,.53,0,.65,-.67,body);tail.rotation.x=-.45;}
if(!animal)g.userData.arms=[limbs[1],limbs[3]];const rig=new T.Group();for(const child of [...g.children])rig.add(child);g.add(rig);g.userData.hitRig=rig;let attackLeft=0,attackDuration=.7,attackKind='';
const castOrb=new T.Mesh(new T.SphereGeometry(.15,10,8),new T.MeshBasicMaterial({color:0x93ff74,transparent:true,opacity:.85}));castOrb.position.set(.35,1.4,.35);castOrb.visible=false;rig.add(castOrb);
const scale=height/(animal?1.25:1.78);g.scale.setScalar(scale);let last=new T.Vector3(x,0,z),phase=0;
return {g,x,z,heading:0,height,cueAttack(kind,duration=.7){attackKind=kind;attackDuration=duration;attackLeft=duration},animate(dt){if(this.stun>0)return;attackLeft=Math.max(0,attackLeft-dt*(this.slow>0?.5:1));rig.position.z=0;rig.rotation.x=0;castOrb.visible=false;for(const l of limbs)l.rotation.z=0;if(attackLeft>0){const t=1-attackLeft/attackDuration,pulse=Math.sin(t*Math.PI);if(attackKind==='bite'){rig.position.z=.32*pulse;rig.rotation.x=-.18*pulse;for(const l of limbs)l.rotation.x=-.65*pulse}else{const arms=g.userData.arms||[limbs[1],limbs[3]];if(attackKind==='claw'){rig.position.z=.35*pulse;for(const [i,a] of arms.entries())if(a){a.rotation.x=-2.1*pulse;a.rotation.z=(i?1:-1)*.55*pulse}}else if(attackKind==='bow'){const draw=t<.26?t/.26:Math.max(0,1-(t-.26)/.12);if(arms[0])arms[0].rotation.x=-1.45;if(arms[1]){arms[1].rotation.x=-1.3+draw*.35;arms[1].rotation.z=-draw*.5}const attr=g.userData.string?.geometry.attributes.position;if(attr){attr.setXYZ(1,0,0,-.25*draw);attr.needsUpdate=true}}else{arms.forEach((a,i)=>{if(a){a.rotation.x=-1.6*pulse;a.rotation.z=(i?1:-1)*pulse*.4}});castOrb.visible=true;castOrb.scale.setScalar(.7+pulse*1.3);rig.rotation.x=-.10*pulse}}}},update(){const speed=g.position.distanceTo(last);last.copy(g.position);if(speed>.0001)phase+=Math.min(.5,speed*8);limbs.forEach((l,i)=>l.rotation.x=speed>.0001?Math.sin(phase+(animal?(i%2):[0,1,1,0][i])*Math.PI)*(!animal&&i%2===1?.35:.55):0);g.rotation.y=this.heading;}};
}

